const {defaults:DEFAULTS,specs,groups,fresh,scores,derive,champion,record,sourceLabel}=Bracket;
const KEY='ncf-legends-2026-double-v2';
let data=fresh(),active='MLBB',selected=null,storageOK=true;
const valid=(v,n)=>v&&Object.keys(DEFAULTS).every(k=>v[k]?.names?.length===8&&v[k].names.every(x=>typeof x==='string')&&v[k]?.games?.length===n&&v[k].games.every(g=>Array.isArray(g)&&g.length===3&&g.every(x=>x===null||x===0||x===1)));
try {const stored=JSON.parse(localStorage.getItem(KEY));if(valid(stored,15))data=stored;else {const old=JSON.parse(localStorage.getItem('ncf-legends-2026-v1'));if(valid(old,7)){for(const k of Object.keys(DEFAULTS)){data[k].names=old[k].names;data[k].games.splice(0,7,...old[k].games);}localStorage.setItem(KEY,JSON.stringify(data));}}}catch{storageOK=false;}
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));storageOK=true}catch{storageOK=false}render()}
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function chooseGame(i,g,side){const t=data[active];if(!record(t,i,g,side))return;save();showMatch(i);const ms=derive(t);if(ms[i].winner!==null)notify(champion(ms)!==null?`${t.names[champion(ms)]} are the champions!`:i===13?'Bracket reset! Both finalists now have one loss.':`${t.names[ms[i].winner]} advance.`);}
function matchHTML(i,m,t){const complete=m.winner!==null;return `<button class="match" data-match="${i}" aria-label="Open match ${i+1}: ${m.seeds.map(s=>s===null?'To be decided':esc(t.names[s])).join(' versus ')}"><div class="match-label"><span>MATCH ${String(i+1).padStart(2,'0')}</span><span class="${m.ready?'ready':''}">${complete?'COMPLETE':!m.enabled?'IF NEEDED':m.ready?'VIEW SERIES ↗':'UPCOMING'}</span></div>${m.seeds.map((seed,k)=>`<div class="team-row ${seed===null?'pending':''} ${complete&&seed===m.winner?'winner':''}"><span class="seed">${seed===null?'—':String(seed+1).padStart(2,'0')}</span><span>${seed===null?sourceLabel(specs[i].sources[k]):esc(t.names[seed])}</span><span class="score">${complete&&seed===m.winner?'✓ &nbsp; ':''}${m.ready?m.score[k]:'—'}</span></div>`).join('')}</button>`}
function render(){const t=data[active],ms=derive(t),champ=champion(ms),complete=ms.filter(m=>m.winner!==null).length,total=ms[14].enabled?15:14;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===active));$('#saved').textContent=storageOK?'Saved on this browser':'Storage unavailable · keep this tab open';$('#progress').innerHTML=`<div style="width:${complete/total*100}%"></div>`;$('#progress').setAttribute('aria-label',`${complete} of ${total} matches completed`);
$('#board').innerHTML=groups.map(group=>`<section class="bracket-group"><div class="group-title">${group.title}<span>${group.title==='UPPER BRACKET'?'First loss → lower bracket':group.title==='LOWER BRACKET'?'Second loss → eliminated':'Lower champion must win both finals'}</span></div><div class="bracket-grid">${group.columns.map(([name,ids])=>`<div class="column"><div class="column-heading">${name}</div><div class="matches">${ids.map(i=>matchHTML(i,ms[i],t)).join('')}</div></div>`).join('')}${group.title==='CHAMPIONSHIP'?`<div class="column"><div class="column-heading">CHAMPION</div><div class="matches"><div class="champion-box"><div class="trophy">♜</div><small>THE CROWN AWAITS</small><h3>${champ===null?'WHO WILL RISE?':esc(t.names[champ])}</h3><p>${champ===null?'Two losses. One last team standing.':`${active} · NCF 2026 champions`}</p></div></div></div>`:''}</div></section>`).join('');document.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>showMatch(Number(b.dataset.match)));drawBracketConnectors();}
function showMatch(i){selected=i;const t=data[active],m=derive(t)[i],games=t.games[i];const name=k=>m.seeds[k]===null?'TBD':esc(t.names[m.seeds[k]]);$('#match-content').innerHTML=`<div class="dialog-top"><p class="eyebrow">${active} / MATCH ${String(i+1).padStart(2,'0')}</p><button data-close aria-label="Close match">✕</button></div><h2>${specs[i].title}</h2><p>${m.ready?'Tap the winner next to each team. First to two wins advances automatically.':(!m.enabled?'The reset final opens only if the lower-bracket champion wins the grand final.':'Complete the preceding matches to unlock this series.')}</p><div class="series-score"><span>${name(0)}</span><span>${m.score[0]} : ${m.score[1]}</span><span>${name(1)}</span></div><div class="rounds">${games.map((v,g)=>{const skip=g===2&&games[0]!==null&&games[0]===games[1];const locked=!m.ready||(g>0&&games[g-1]===null)||skip;return `<div class="round"><h3>GAME 0${g+1}</h3>${[0,1].map(k=>`<button data-game="${g}" data-side="${k}" ${locked?'disabled':''} class="${v===k?'chosen':''}" aria-pressed="${v===k}">${name(k)} &nbsp; ${v===k?'✓':'+'}</button>`).join('')}<p>${skip?'Not needed':v!==null?'Winner recorded':locked?'Awaiting prior game':'Select winner'}</p></div>`}).join('')}</div><div class="dialog-bottom"><span>${m.winner===null?'Best of 3 · Two wins to advance':`${esc(t.names[m.winner])} ${champion(derive(t))===m.winner?'win the tournament':'advance'} ✓`}</span><button data-close>Done</button></div><p>To correct a result, tap the selected winner again or choose the other team. Later games and affected matchups will clear.</p>`;$('#match-content').querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>chooseGame(i,Number(b.dataset.game),Number(b.dataset.side)));bindClose();if(!$('#match-dialog').open)$('#match-dialog').showModal();}
function bindClose(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close())}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{active=b.dataset.tab;render()});
$('#edit').onclick=()=>{$('#team-fields').innerHTML=data[active].names.map((n,i)=>`<label>SEED ${String(i+1).padStart(2,'0')}<input name="team${i}" value="${esc(n)}" required maxlength="32" aria-label="Team ${i+1}"></label>`).join('');$('#team-dialog').showModal()};
$('#team-form').onsubmit=e=>{e.preventDefault();const names=Array.from($('#team-fields').querySelectorAll('input')).map(x=>x.value.trim());if(names.some(n=>!n))return notify('Every team needs a name.');if(new Set(names.map(n=>n.toLowerCase())).size<8)return notify('Please give each team a unique name.');data[active].names=names;save();$('#team-dialog').close();notify('Team names updated.')};
$('#reset').onclick=()=>{if(confirm(`Reset all ${active} results? Team names will stay. This cannot be undone.`)){data[active].games=Array.from({length:15},()=>[null,null,null]);save();notify(`${active} bracket reset.`)}};
function exportPDF(){const t=data[active],ms=derive(t),champ=champion(ms);const header=`<h1>NCF INTRAMURALS 2026 · ${active}</h1><p>DOUBLE ELIMINATION | 8 TEAMS | BEST OF 3 | Two series losses eliminate a team</p>`;$('#print-view').innerHTML=groups.map(group=>`<section>${header}<h2>${group.title}</h2><div class="print-bracket">${group.columns.map(([title,ids])=>`<div><h3>${title}</h3><div class="print-column">${ids.map(i=>`<div class="print-match" data-match="${i}"><small>M${i+1} · ${specs[i].title}</small>${ms[i].seeds.map((s,k)=>`<div>${s===null?sourceLabel(specs[i].sources[k]):esc(t.names[s])} — ${ms[i].score[k]}${s!==null&&s===ms[i].winner?' ✓':''}</div>`).join('')}${!ms[i].enabled?'<b>Only if lower champion wins M14</b>':''}</div>`).join('')}</div></div>`).join('')}</div>${group.title==='CHAMPIONSHIP'?`<h2>Champion: ${champ===null?'To be decided':esc(t.names[champ])}</h2><p>If the upper champion wins M14, no reset is needed. If the lower champion wins M14, M15 decides the championship.</p>`:''}<footer>Exported ${new Date().toLocaleString('en-PH',{timeZone:'Asia/Manila'})} (Philippine time) · Current bracket state</footer></section>`).join('')+`<section>${header}<h2>GAME-BY-GAME RESULTS</h2><table><thead><tr><th>Match</th><th>Teams</th><th>Game 1</th><th>Game 2</th><th>Game 3</th><th>Winner</th></tr></thead><tbody>${ms.map((m,i)=>`<tr><td>M${i+1}</td><td>${m.seeds.map(s=>s===null?'TBD':esc(t.names[s])).join(' vs ')}</td>${t.games[i].map((g,j)=>`<td>${!m.enabled?'If needed':g===null?(j===2&&t.games[i][0]!==null&&t.games[i][0]===t.games[i][1]?'Not needed':'Pending'):esc(t.names[m.seeds[g]]??'TBD')}</td>`).join('')}<td>${m.winner===null?'Pending':esc(t.names[m.winner])}</td></tr>`).join('')}</tbody></table></section>`;document.title=`NCF-2026-${active}-Double-Elimination`;drawBracketConnectors();window.print();document.title='Call of Legends · NCF Intramurals 2026';}
$('#export').onclick=exportPDF;bindClose();render();
